INSERT INTO `home_notices` (`id_home_notice`, `category`, `title_es`, `body_es`, `title_en`, `body_en`, `is_active`, `is_featured`, `starts_at`, `ends_at`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'internal_notice', 'Demo CIETE v2.1.0 preparada para revisión', 'La versión v2.1.0 queda preparada con datos reales importados, validación técnica completada y casos de prueba para revisar el flujo diario de trabajo.', 'CIETE v2.1.0 demo ready for review', 'Version v2.1.0 is ready with real imported data, completed technical validation and test cases for reviewing the daily workflow.', 1, 1, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(2, 'internal_notice', 'Revisión operativa con datos reales', 'La base local trabaja ya con datos reales de MOEVE y REPSOL. Si detectas importes, fechas o referencias extrañas, revísalos como avisos de origen antes de corregirlos.', 'Operational review with real data', 'The local database now uses real MOEVE and REPSOL data. If you detect unusual amounts, dates or references, review them as source-data warnings before correcting anything.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(3, 'internal_notice', 'Contextos reales activos', 'El selector de contexto solo permite MOEVE, REPSOL y OTROS CLIENTES. La vista global TODOS no está disponible para operar ni crear registros.', 'Real contexts enabled', 'The context selector only allows MOEVE, REPSOL and OTHER CLIENTS. The global ALL view is not available for operating or creating records.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(4, 'internal_notice', 'Uso del modo Excel', 'El modo Ciete Excel está pensado para trabajo diario con tablas densas. Usa filtros, paginación e Ir a página para moverte rápido por grandes volúmenes.', 'Using Excel mode', 'Ciete Excel mode is designed for daily work with dense tables. Use filters, pagination and Go to page to move quickly through large datasets.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(5, 'system_update', 'Importación real completada', 'Se han cargado 11 Excel operativos con trabajos, pedidos, ítems y facturas reales. Los conteos principales están reconciliados con la referencia P1-12.', 'Real import completed', '11 operational Excel files have been loaded with real jobs, orders, items and invoices. The main counts are reconciled with the P1-12 reference.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(6, 'system_update', 'Paginación mejorada', 'Los listados principales incorporan navegación rápida con primera página, última página e Ir a página para reducir tiempos de trabajo.', 'Improved pagination', 'Main listings now include faster navigation with first page, last page and Go to page to reduce working time.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(7, 'system_update', 'Control de edición por celda', 'En Trabajos Excel, si otro usuario modificó una celda recientemente, el sistema avisa, conserva tu borrador y pide confirmación antes de sobrescribir.', 'Cell edit conflict control', 'In Jobs Excel mode, if another user recently changed a cell, the system warns you, keeps your draft and asks for confirmation before overwriting.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(8, 'company_news', 'Versión v2.1.0 disponible', 'La versión v2.1.0 queda disponible para validación operativa local, con roles, permisos, contextos y datos reales cargados.', 'Version v2.1.0 available', 'Version v2.1.0 is available for local operational validation, with roles, permissions, contexts and real data loaded.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(9, 'company_news', 'Panel técnico más limpio', 'El administrador técnico cuenta con un panel más ordenado para usuarios, soporte, auditoría técnica, mantenimiento, avisos y estado del sistema.', 'Cleaner technical panel', 'The technical administrator now has a cleaner panel for users, support, technical audit, maintenance, notices and system status.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14'),
(10, 'company_news', 'Validación por roles preparada', 'El ERP está preparado para probar el día a día de Dirección, Contabilidad, Ejecución MOEVE, Ejecución REPSOL, multicontexto y administración técnica.', 'Role-based validation ready', 'The ERP is ready to test daily work for Management, Accounting, MOEVE Execution, REPSOL Execution, multicontext users and technical administration.', 1, 0, NULL, NULL, 1, 1, '2026-05-19 04:32:14', '2026-05-19 04:32:14');
